// lib/automation/faq-engine.ts
async function matchFaq(params) {
  const { workspaceId, instagramAccountId, messageText } = params;
  if (!messageText || messageText.trim().length === 0) {
    return { matched: false };
  }
  const faqItems = await prisma.faqItem.findMany({
    where: {
      workspaceId,
      instagramAccountId,
      isActive: true
    },
    orderBy: { order: "asc" }
  });
  for (const faq of faqItems) {
    const keywords = faq.keywords || [];
    const match = matchKeywords(messageText, keywords, false);
    if (match.matched) {
      return {
        matched: true,
        faqId: faq.id,
        question: faq.question,
        answerText: faq.answerText,
        linkUrl: faq.linkUrl ?? void 0
      };
    }
  }
  return { matched: false };
}

